var e=JSON.parse(`[{"id":"start","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"4505f3a407621163","vermerk":"Bestand"},"gebiet":"","titel":"Willkommen: Warum eine Landkarte?","kern":"Du lernst, wie das Buch „Landkarte der Realität“ gebaut ist und warum es dir Werkzeuge gibt, mit denen du selbst prüfen und eigene Karten zeichnen kannst.","dauer":5,"schritte":[{"titel":"Ein Bild zum Start: die Höhle","text":"Der Prolog beginnt mit einem Bild. Du sitzt gefangen in einer Höhle und starrst auf eine Felswand. Davor tanzen Schatten. Du hältst sie für alles, was ist. Eines Tages spürst du einen Riss in deiner Überzeugung. Du drehst dich um. Die echten Gegenstände wirken zugleich realer und fremder als die Schatten. Das Buch führt dich nicht gewaltsam aus der Höhle. Es gibt dir Werkzeuge an die Hand."},{"titel":"Was ist die Landkarte der Realität?","text":"Aus den Werkzeugen sollst du deine eigene, wahrhaftige Landkarte zeichnen. Deshalb nennt dich der Prolog „werdenden Kartenzeichner“. Er beschreibt die Werkzeuge in drei Bildern. Ein Kompass hilft, Täuschungen zu entlarven, die wie die Sprache der Wahrheit klingen. Ein Skalpell untersucht die Welt Schicht für Schicht. Und ein Samen lässt dich einen Garten der Wahrheit kultivieren."},{"titel":"Karte und Wirklichkeit","text":"Eine Karte zeigt ein Land, aber sie ist nicht das Land selbst. Dieses Bild stammt aus dieser Lektion, nicht aus dem Buch. Das Buch sagt: Eine Karte bleibt ein Stück Papier, wenn man nicht gelernt hat, sie zu lesen und nach ihr zu navigieren. Die Autoren nennen ihr Werk die ehrgeizigste Karte, die sie zeichnen konnten, und doch nur eine Insel im Ozean des Unbekannten. Darum sollst du Karten prüfen und selbst bessere zeichnen."},{"titel":"Wie das Buch gebaut ist","text":"Das Buch besteht aus zwei Büchern. Das erste ist die Reise: acht Bände, die du der Reihe nach gehst. Das zweite ist die Werkstatt, die du in jeder Reihenfolge betreten kannst. Dort stehen die Werkstücke, das sind die Bausteine des Buches. Das Große Glossar der Werkstatt ordnet sie in acht Gebiete von A bis H (im Buch „Cluster“ genannt). Ein Einstieg ist Teil I der Werkstatt, der Kompass. Er bietet schnelle Werkzeuge wie das Fünf-Finger-Protokoll zum Prüfen von Quellen."},{"titel":"Irrtum ist menschlich","text":"Im Epilog gestehen die Autoren zwei Dinge. Erstens: Sie sind nicht allwissend. Zweitens: Sie sind nicht fehlerfrei, denn auch sie sind anfällig für Denkfehler. Deshalb sollst du die Werkzeuge auf das Buch selbst anwenden. Nimm das Wort der Autoren nicht als Evangelium, sondern als Hypothese. Fehler zu finden ist hier ausdrücklich erwünscht. Ein Fund ist kein Makel, denn die Autoren wollen, dass du ihnen widersprichst."}],"beispiel":{"titel":"Gedankenspiel: Die Brücke, die nicht auf der Karte steht","text":"Gedankenspiel: Du wanderst mit einer Karte. Am Fluss steht eine Brücke, die auf der Karte fehlt. Wer der Karte blind folgt, steht ratlos am Ufer. Wer die Brücke sieht, glaubt seinen Augen und zeichnet sie auf der Karte nach. Das passt zum Buch: Es will, dass du Karten liest, mit der Wirklichkeit abgleichst und dich nicht schämst, wenn die Karte etwas übersehen hat, auch die Karte des Buches."},"merksatz":"Das Buch will, dass du selbst Karten zeichnest, und dass du auch ihm widersprichst.","pruefen":[{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Was gibt dir das Buch laut Prolog an die Hand?","optionen":["Fertige Antworten auf alle Fragen","Werkzeuge, mit denen du deine eigene Landkarte zeichnen kannst","Eine Liste von Menschen, denen du nicht glauben darfst"],"richtig":1,"erklaerung":"Der Prolog verspricht Werkzeuge. Mit ihnen sollst du das Licht verstehen und deine eigene, wahrhaftige Landkarte zeichnen."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Was sagen die Autoren im Epilog über sich selbst?","optionen":["Ihre Karte ist vollständig und fehlerfrei, deshalb brauchst du sie nicht zu prüfen","Sie sind unfehlbar, auch wenn manche Küsten ihrer Karte noch fehlen","Sie sind nicht allwissend und nicht fehlerfrei, deshalb sollst du ihr Buch prüfen"],"richtig":2,"erklaerung":"Der Epilog nennt beides ausdrücklich: nicht allwissend, nicht fehlerfrei. Darum fordert er dich auf, die Werkzeuge auf das Buch selbst anzuwenden."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Wie ist das Buch aufgebaut?","optionen":["Zwei Bücher: die Reise der Reihe nach, die Werkstatt in jeder Reihenfolge","Ein einziger Text, der nur von vorn nach hinten gelesen werden darf","Nur ein Lexikon zum Nachschlagen, eine Reise gibt es nicht"],"richtig":0,"erklaerung":"Das erste Buch ist die Reise mit acht Bänden, das zweite die Werkstatt mit den Werkstücken. Die Werkstatt kannst du in jeder Reihenfolge betreten."}],"werkstuecke":[],"buch":"Landkarte der Realität, Prolog, Entdeckungsreise, Kompass und Epilog","schaubild":"schaubild-1-landkarte-des-werks"},{"id":"a","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"ee9cfd8dee9bf3e6","vermerk":"Bestand"},"gebiet":"A","titel":"Wie prüfe ich eine Behauptung?","kern":"Vier einfache Werkzeuge helfen dir, eine Behauptung zu prüfen, bevor du sie glaubst oder weitergibst.","dauer":6,"schritte":[{"titel":"Die einfachste Erklärung zuerst","text":"Das Buch nennt seine Bausteine „Werkstücke“. Jedes Werkstück erklärt ein Denkwerkzeug. Das erste heißt Ockhams Rasiermesser. Wenn mehrere Erklärungen möglich sind, bevorzuge die mit den wenigsten unbewiesenen Annahmen. Ein zerbrochener Keks lag eher an einer Erschütterung durch einen LKW als an unsichtbaren Kobolden. Das beweist nichts, aber es ist der bessere Startpunkt. Die Frage dazu: „Welche neuen Welten muss ich erfinden, damit diese Erklärung wahr ist?“"},{"titel":"Eine Behauptung muss scheitern können","text":"Stell dir einen unsichtbaren, körperlosen Drachen in einer Garage vor. Jeden Test erklärt sein Besitzer für unmöglich. Dann ist kaum noch ein Unterschied zu gar keinem Drachen. Das ist die Falsifizierbarkeit: Eine Aussage ist nur wertvoll, wenn es eine denkbare Beobachtung gibt, die sie widerlegen könnte. Gute Theorien legen sozusagen ihren Hals auf den Block. Frag also: „Was müsste passieren, damit du die Idee für falsch hältst?“"},{"titel":"Wer behauptet, muss belegen","text":"Der Philosoph Bertrand Russell erzählt im Gedankenspiel von einer winzigen Teekanne, die zwischen Erde und Mars die Sonne umkreist. „Beweise mir, dass sie nicht da ist!“ Das kann niemand. Deshalb gilt die Beweislast: Wer etwas behauptet, muss die Beweise liefern, nicht der Zweifler. Und außergewöhnliche Behauptungen brauchen außergewöhnliche Beweise. Dass jemand das Gegenteil nicht beweisen kann, ist noch kein Beleg."},{"titel":"Gemeinsam heißt nicht verursacht","text":"Wo viele Störche nisten, werden viele Kinder geboren. Das Buch zeigt es mit Zahlen aus 17 europäischen Ländern: Die Korrelation liegt bei 0,62. Bringen die Störche die Babys? Nein. Dahinter steckt vor allem die Größe des Landes und das Leben auf dem Land: Große, ländliche Länder haben mehr Platz für Störche und mehr Einwohner. Das ist der Unterschied zwischen Korrelation, also gemeinsamem Auftreten, und Kausalität, also Ursache und Wirkung. Frag immer: „Welcher unsichtbare Faktor C könnte beides verursachen?“"},{"titel":"Dein Werkzeugkasten","text":"Diese vier Werkzeuge gehören zum Gebiet A, den Werkzeugen des Denkens. Sie sind keine fertigen Antworten, sondern Grundinstrumente, mit denen du jede Behauptung untersuchen kannst. Sie prüfen die Behauptung, nicht den Menschen, der sie sagt. Du musst nicht alle auf einmal anwenden. Schon eine der vier Fragen kann ein Gespräch ruhiger machen, und sie hilft dir auch bei deinen eigenen Überzeugungen."}],"beispiel":{"titel":"Gedankenspiel: Mias Glückssocken","text":"Gedankenspiel: Mia trägt zu jedem Spiel ihres Teams ihre Glückssocken. Das Team gewinnt. „Die Socken wirken!“, sagt sie. Prüfe mit den Werkzeugen. Gemeinsames Auftreten ist noch keine Ursache. Vielleicht hat das Team einfach fleißig trainiert, das wäre ein Faktor C. Vielleicht ist es auch Zufall. Und wer die Wirkung der Socken behauptet, muss sie belegen. Frag freundlich: „Was müsste passieren, damit du glaubst, dass sie nichts bewirken?“ Sie darf ihre Socken trotzdem behalten."},"merksatz":"Frag bei jeder Behauptung: Wer belegt das, was könnte es widerlegen und was könnte dahinterstecken?","pruefen":[{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Erklärung nennt das Buch als Autorität (Konzept 6.2); in Phase 3 umschreiben.","frage":"Dein WLAN fällt aus. Welche Erklärung prüft Ockhams Rasiermesser zuerst?","optionen":["Ein ausländischer Geheimdienst greift dein Heimnetz an","Der Router muss neu gestartet werden","Beide Erklärungen sind gleich wahrscheinlich"],"richtig":1,"erklaerung":"Der Router kommt mit bekannten Annahmen aus, der Geheimdienst braucht viele neue und unbewiesene. Das Buch empfiehlt, mit der einfachsten Lösung zu beginnen."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Jemand sagt: „Beweise mir, dass meine Teekanne nicht um die Sonne kreist!“ Wer muss laut Buch Beweise liefern?","optionen":["Die Person, die zweifelt","Niemand, beide Seiten sind gleich im Recht","Die Person, die die Behauptung aufstellt"],"richtig":2,"erklaerung":"Die Beweislast liegt beim Behauptenden. Man kann nicht beweisen, dass etwas im ganzen Universum nicht existiert, deshalb darf der Zweifler die Behauptung vorläufig verwerfen."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Das Buch erzählt: In Ländern mit vielen Storchenpaaren werden viele Kinder geboren. Wie erklärt es das?","optionen":["Ein dritter Faktor: die Größe des Landes und das Leben auf dem Land","Die Störche bringen die Babys, denn die Zahlen zeigen den Zusammenhang","Die Zahlen stimmen nicht, jemand hat sie erfunden"],"richtig":0,"erklaerung":"Die Daten waren klar, aber die Ursache liegt woanders. Die Größe des Landes und die ländliche Lebensweise erklären beides, also verursacht ein dritter Faktor beides."}],"werkstuecke":["A.1.1 Ockhams Rasiermesser","A.3 Falsifizierbarkeit","A.4 Die Beweislast (Burden of Proof)","A.5 Korrelation vs. Kausalität"],"buch":"Landkarte der Realität, Glossar, Gebiet A: Die Werkzeuge des Denkens"},{"id":"a2","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"16c971fb9fd36979","vermerk":"Bestand"},"gebiet":"A","titel":"Zahlen richtig lesen","kern":"Zahlen können täuschen, je nachdem, wie du sie ansiehst; wenn du Menschen zählst und nach Gruppen aufteilst, siehst du klarer.","dauer":6,"schritte":[{"titel":"Eine Zahl ist noch kein Urteil","text":"Ein Test, der „zu 99 Prozent genau“ ist, klingt nach Sicherheit. Doch unser Gehirn liebt klare, einfache Antworten und liest Zahlen deshalb oft zu schnell. Die Zahl allein sagt nicht, was sie für dich bedeutet. In dieser Lektion lernst du zwei Griffe aus der „Landkarte der Realität“: Zahlen in Menschen übersetzen und Zahlen nach Gruppen aufteilen. Beides findest du als Baustein des Buches, genannt Werkstück, im Gebiet A."},{"titel":"Das Rätsel des Arztes","text":"Stell dir vor, eine seltene Krankheit betrifft 1 von 10.000 Menschen. Ein Test erkennt 99 Prozent der Kranken (das nennt man Sensitivität) und 99 Prozent der Gesunden (das nennt man Spezifität). Du machst ihn aus Routine, ohne Symptome, und er ist positiv. Dein Instinkt sagt: „99 Prozent genau, also bin ich zu 99 Prozent krank.“ Stimmt das? Das Buch rechnet es dir vor, und zwar mit Menschen statt mit Prozenten."},{"titel":"Menschen zählen statt Prozente rechnen","text":"Das Buch nennt den Ausgangspunkt die Basisrate: Wie häufig ist die Krankheit überhaupt? Nimm 1 Million Menschen. Bei 1 von 10.000 sind 100 krank und 999.900 gesund. Von den 100 Kranken testen 99 positiv. Von den Gesunden testet 1 Prozent fälschlich positiv, das sind 9.999. Zusammen gibt es 10.098 positive Tests, nur 99 davon sind echt. Das ist weniger als 1 Prozent. Das Schaubild im nächsten Schritt zeigt diesen Baum."},{"titel":"Wenn das Ganze etwas anderes sagt als die Teile","text":"Ein zweiter Stolperstein: Zahlen, die alles zusammenwerfen. 1973 ließ die Universität Berkeley laut Buch 44 Prozent der männlichen, aber nur 35 Prozent der weiblichen Bewerber zum Graduiertenstudium zu. Das sah nach Diskriminierung aus. Nach Fachbereichen aufgeteilt, kehrte sich das Bild um: Frauen hatten sich überproportional in Fächern mit den niedrigsten Zulassungsquoten beworben. Das Muster heißt Simpson-Paradox. Das Schaubild zeigt nur die sechs größten Fachbereiche, dort sind es 45 und 30 Prozent."},{"titel":"Die zwei Fragen für unterwegs","text":"Aus beiden Fällen entstehen zwei Fragen. Die erste: „Was ist die Basisrate, also wie wahrscheinlich war es, bevor es diesen neuen Beweis gab?“ Die zweite: „Bleibt der Zusammenhang bestehen, wenn ich die Gruppen aufteile, und wer hat entschieden, wie aufgeteilt wird?“ Beim Aufteilen suchst du nach einem verborgenen dritten Faktor, der die Gruppen ungleich verteilt. Du musst dafür kein Mathematiker sein. Es genügt, genauer hinzusehen."}],"beispiel":{"titel":"Der Baum und die zwei Balkenbilder","text":"Das erste Schaubild ist ein Baum. Oben stehen 1.000.000 Menschen, darunter links die 100 Kranken, rechts 999.900 Gesunde. Von den Kranken testen 99 positiv, 1 negativ. Von den Gesunden testen 9.999 fälschlich positiv. Unten: 10.098 positive Tests, nur 99 davon echt. Das Bild rundet auf „etwa 1 Prozent“, der Text sagt „weniger als 1 Prozent“. Das zweite Schaubild zeigt Berkeley 1973. Links die sechs größten Fächer zusammen: Männer 45 Prozent zugelassen, Frauen 30. Rechts A bis F einzeln: In vier von sechs liegen die Frauen gleichauf oder vorn. 51 Prozent der Männer, aber nur 7 Prozent der Frauen bewarben sich in A und B, den Fächern mit den höchsten Quoten."},"merksatz":"Zähle Menschen statt Prozente, und teile die Gruppen auf, bevor du einer Zahl glaubst.","pruefen":[{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"c68d96518a83df96","vermerk":"Bestand"},"frage":"Im Baum sind 99 Kranke positiv und 9.999 Gesunde fälschlich positiv. Wie viele positive Tests gibt es, und wie viele davon sind echt?","optionen":["Es gibt 10.098 positive Tests, davon sind 99 echt.","Es gibt 10.098 positive Tests, davon sind 9.999 echt.","Es gibt 99 positive Tests, und alle sind echt."],"richtig":0,"erklaerung":"Du zählst 99 und 9.999 zusammen und kommst auf 10.098 positive Tests. Echt sind nur die 99 Tests bei den Kranken. Die 9.999 anderen sind falscher Alarm bei Gesunden."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"54fb3418f41f5d93","vermerk":"Bestand"},"frage":"Warum ist ein positiver Test trotz „99 Prozent genau“ bei dieser seltenen Krankheit meist ein falscher Alarm?","optionen":["Weil der Test in Wahrheit nur zu 50 Prozent genau ist und das vor den Getesteten verschwiegen wird.","Weil gesunde Menschen bei einem Test grundsätzlich viel öfter positiv sein werden als kranke.","Weil sehr viele Gesunde getestet werden und ihre wenigen Fehler zahlreicher sind als die echten Treffer."],"richtig":2,"erklaerung":"Die Krankheit ist selten (Basisrate 1 von 10.000). Darum gibt es sehr viele Gesunde, und 1 Prozent von ihnen sind 9.999 Menschen, weit mehr als die 99 echten Treffer."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"0d09a071644a4d92","vermerk":"Bestand"},"frage":"Warum sah es in Berkeley zusammengerechnet nach Benachteiligung der Frauen aus?","optionen":["In jedem einzelnen Fach wurden Frauen deutlich seltener zugelassen als Männer.","Frauen hatten sich überproportional in Fächern mit den niedrigsten Quoten beworben.","Die Zahlen der Frauen waren beim Zusammenrechnen versehentlich falsch addiert worden."],"richtig":1,"erklaerung":"Aufgeteilt nach Fächern lagen die Frauen in den meisten gleichauf oder vorn. Der Gesamtunterschied entstand durch die Verteilung der Bewerbungen auf leichte und schwere Fächer."}],"werkstuecke":["A.7 Probabilistisches Denken","A.24 Die Anatomie einer Studie, zweiter Blick","A.5 Korrelation vs. Kausalität"],"buch":"Landkarte der Realität, Glossar, Gebiet A: Die Werkzeuge des Denkens","schaubilder":["schaubild-5-haeufigkeitsbaum","schaubild-8-simpson-paradox"],"hinweis":"Hinweis: Diese Lektion erklärt, wie man Zahlen und Behauptungen prüft. Sie ist keine Behandlungs- oder Gesundheitsempfehlung und ersetzt keine ärztliche Beratung."},{"id":"a3","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"64fea264ce2e789c","vermerk":"Bestand"},"gebiet":"A","titel":"Systeme verstehen","kern":"Viele Dinge verhalten sich wie Kreisläufe, die sich ausgleichen oder aufschaukeln, und manchmal kippen sie plötzlich.","dauer":6,"schritte":[{"titel":"Vom Strich zum Kreis","text":"Oft denken wir in einfachen Ketten: Ich tue A, dann passiert B. Das Buch nennt das lineares Denken. Es reicht für die Herdplatte, aber nicht für komplexe Systeme wie eine Gesellschaft oder einen Körper. Dort hängt vieles miteinander zusammen. Der Baustein des Buches dazu heißt Systemdenken. Sein wichtigstes Werkzeug ist die Feedback-Schleife: Das Ergebnis einer Handlung fließt als neue Information in dieselbe Handlung zurück."},{"titel":"Die ausgleichende Schleife","text":"Der Thermostat ist das Lehrbeispiel. Du stellst 21 °C ein, das ist das Ziel. Ein Sensor misst 19 °C, es ist zu kalt, also kommt das Signal „Heizen!“. Die Heizung läuft, bis der Sensor 21 °C misst, dann kommt „Stopp!“. Jede Runde macht die Abweichung kleiner. Solche Schleifen stabilisieren und suchen ein Ziel. Auch Körpertemperatur und Hungergefühl funktionieren so. Das Schaubild im nächsten Schritt zeigt diesen Kreislauf links."},{"titel":"Die verstärkende Schleife","text":"Die zweite Art arbeitet anders: Mehr von X führt zu noch mehr von X. Beim viralen Video bringen mehr Views mehr Empfehlungen durch den Algorithmus, mehr Empfehlungen bringen mehr Shares, und mehr Shares bringen noch mehr Views. Jede Runde macht die nächste größer. Dasselbe Muster steckt im Zinseszins, in Gerüchten und in der Massenpanik. Wird sie nicht gebremst, führt sie zur Eskalation oder zum Kollaps. Im Schaubild steht sie rechts."},{"titel":"Der Kipppunkt","text":"Ein Kipppunkt ist ein Schwellenwert, an dem eine winzige Änderung das ganze System plötzlich in einen anderen Zustand bringt, oft unumkehrbar. Du schiebst ein Glas Zentimeter für Zentimeter über den Tisch, es bewegt sich gleichmäßig. Ein weiterer Millimeter über die Kante, und es stürzt. Das Video wächst täglich um 10 Views, bis ein einflussreicher Account es teilt. Dann zündet die verstärkende Schleife. „Vier Schübe“ und „Tag 4“ stehen nur im Schaubild, nicht im Buchtext."},{"titel":"Die Kante rechtzeitig sehen","text":"Das Buch gibt dir vier Detektor-Fragen. Die Motoren: Welche verstärkenden Schleifen sehe ich? Die Bremsen: Welche ausgleichenden Schleifen sollten wirken, und warum versagen sie? Die Spannung: Wie geladen ist das System? Der Auslöser: Was wäre der kleinste Funke? Frag außerdem: „Wie hat das System auf meine Handlung reagiert?“ Und sieh nicht überall Kipppunkte, sonst wird das Werkzeug zur Paranoia."}],"beispiel":{"titel":"Thermostat, Video und Tischkante","text":"Das erste Schaubild zeigt zwei Kreisläufe. Links der Thermostat: Ziel 21 °C, Sensor 19 °C, Signal „Heizen!“, Heizung läuft, Sensor 21 °C, Signal „Stopp!“. Wirkung: Stabilität. Rechts das virale Video: mehr Views, mehr Empfehlungen, mehr Shares, noch mehr Views, bis zu 1.000.000. Wirkung: Eskalation oder Kollaps. Das zweite Schaubild zeigt den Kipppunkt. Links das Glas: vier gleiche Schübe von je 1 cm, dann ein winziges Plus von 1 mm an der Kante. Rechts das Video: Tag 1 bis 3 mit 50, 60 und 70 Views. Am Tag 4 teilt ein einflussreicher Account es, danach stehen dort 1.000.000 Views."},"merksatz":"Frag nicht nur, was deine Handlung bewirkt, sondern wie das System darauf antwortet.","pruefen":[{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"bda94ead1c8c0ac5","vermerk":"Bestand"},"frage":"Im Schaubild hat das Video an den Tagen 1 bis 3 genau 50, 60 und 70 Views. Am Tag 4 teilt ein einflussreicher Account es. Was zeigt das Schaubild danach?","optionen":["Es wächst weiter gleichmäßig um 10 pro Tag und hat am vierten Tag 80 Views.","Die verstärkende Schleife zündet, und die Zahl springt auf 1.000.000 Views.","Eine ausgleichende Schleife bremst es, und die Views fallen auf null zurück."],"richtig":1,"erklaerung":"Bis Tag 3 wächst es gleichmäßig um 10 pro Tag. Der Auslöser überschreitet die Schwelle, die verstärkende Schleife übernimmt, und das Wachstum wird sprunghaft."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"aa7770deb3340fbe","vermerk":"Bestand"},"frage":"Was unterscheidet die ausgleichende von der verstärkenden Schleife?","optionen":["Die ausgleichende sucht ein Ziel und stabilisiert, die verstärkende macht aus „mehr“ immer „noch mehr“.","Die ausgleichende macht aus „mehr“ immer „noch mehr“, die verstärkende sucht ein Ziel und stabilisiert.","Es gibt keinen Unterschied, denn beide steigern sich mit jeder Runde immer weiter und weiter."],"richtig":0,"erklaerung":"Der Thermostat hält die Temperatur nahe am Ziel, das virale Video schaukelt sich auf. Der eine Typ dämpft die Abweichung, der andere vergrößert sie."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"72d6bf6efee170f7","vermerk":"Bestand"},"frage":"Warum ist die Tischkante ein Kipppunkt?","optionen":["Weil der letzte Schub viel größer war als alle Schübe davor zusammen.","Weil das Glas mit jedem Zentimeter immer schwerer geworden ist.","Weil schon ein winziger Schub die Schwelle überschreitet und das System kippt."],"richtig":2,"erklaerung":"Der letzte Millimeter war nicht größer als die Schübe zuvor. Entscheidend ist, dass er die Schwelle überschritt. Deshalb lohnt es sich, die Kante zu suchen, bevor das Glas fällt."}],"werkstuecke":["A.6 Systemdenken","A.8.1 Die Feedback-Schleife","A.23 Der Kipppunkt-Detektor"],"buch":"Landkarte der Realität, Glossar, Gebiet A: Die Werkzeuge des Denkens","schaubilder":["schaubild-6-feedback-schleifen","schaubild-7-kipppunkt"]},{"id":"a4","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"73cf56c22aec0c19","vermerk":"Bestand"},"gebiet":"A","titel":"Wie gut ist ein Beleg?","kern":"Nicht jeder Beleg wiegt gleich viel, und manchmal liegt das Wichtigste in einer Schublade, die du nie siehst.","dauer":6,"schritte":[{"titel":"Zwei Beweisstücke auf dem Tisch","text":"Das Buch erzählt von Onkel Helmut. Er raucht seit 70 Jahren zwei Schachteln am Tag, ist 95 und sagt: „Schau mich an!“ Seine Geschichte ist wahr. Dagegen steht eine Studie, die über 34.000 britische Ärzte 50 Jahre lang beobachtete: Männer, die ein Leben lang rauchten, starben im Durchschnitt rund 10 Jahre früher als lebenslange Nichtraucher. Wem vertraust du instinktiv? Laut Buch gibt unser Gehirn der lebendigen Geschichte oft mehr Gewicht. Der Baustein des Buches, genannt Werkstück, zeigt: Nicht alle Beweise sind gleichwertig."},{"titel":"Die unteren Stufen der Pyramide","text":"Das Schaubild im nächsten Schritt ordnet Belege als Pyramide mit fünf Stufen. Ganz unten, breit und wackelig, stehen Anekdoten (Stufe 1) und Expertenmeinungen (Stufe 2). Eine Anekdote ist eine einzelne Geschichte, eine Expertenmeinung ohne Daten nur eine hochqualifizierte Vermutung. Darüber, auf Stufe 3, liegen Beobachtungsstudien, etwa Kohorten- und Fall-Kontroll-Studien. Sie sind viel wertvoller als Anekdoten, beweisen aber keine endgültige Ursache."},{"titel":"Die oberen Stufen","text":"Stufe 4 sind randomisierte kontrollierte Studien. Eine Gruppe wird per Zufall geteilt: Eine erhält die echte Behandlung, die andere ein Placebo, also eine Scheinbehandlung. Das Buch nennt sie den Goldstandard. Ganz oben stehen systematische Reviews und Meta-Analysen. Sie fassen alle guten Studien zu einer Frage zusammen und schützen so vor dem Rosinenpicken. Doch die Pyramide ist eine vereinfachte Lehrfassung. Die Qualität der einzelnen Studie bleibt immer entscheidend."},{"titel":"Die Schublade","text":"Selbst saubere Studien können täuschen, wenn nicht alle ans Licht kommen. Positive Ergebnisse werden häufiger eingereicht, angenommen und zitiert. Der Psychologe Robert Rosenthal nannte das 1979 das Schubladenproblem. Das Buch berichtet: 2008 verglich Erick Turner zwölf Antidepressiva. 94 Prozent der veröffentlichten Studien waren positiv, aber nur 51 Prozent der bei der US-Arzneimittelbehörde FDA angemeldeten. Keine Studie musste gefälscht sein. Die Täuschung lag in der Schublade."},{"titel":"Die leere Ecke sehen","text":"Wie erkennt man, was fehlt? Im Trichterplot ist jeder Punkt eine Studie: Wirkung nach rechts, Größe nach oben. Kleine Studien streuen breit, große liegen eng zusammen, es ergibt sich ein symmetrischer Trichter. Fehlt die Seite der kleinen Studien mit negativer Wirkung, ist das ein starkes Warnzeichen für eine volle Schublade, wenn auch nicht der einzige mögliche Grund. Frag deshalb: „Wie viele Studien wurden begonnen, und wie viele sind erschienen?“ Das Schaubild im nächsten Schritt zeigt beide Fälle."},{"titel":"Auch ein KI-Ergebnis ist kein Beleg","text":"Viele fragen heute eine KI nach Belegen. Das Buch warnt: Was ein Sprachmodell liefert, ist eine Liste von Kandidaten, keine Quelle. Sie kann erfunden sein, etwas anderes sagen oder überholt sein, und die Zusammenfassung kann das Ergebnis verdrehen. Auch das Gegenteil kommt vor: In einem Test von 2025 (Columbia Journalism Review) hielt jedes von sieben Modellen mindestens eines von zehn echten Pressefotos für KI-erzeugt. Öffne die Quelle selbst und lies die Kernaussage im Original. Erst dann ist es ein Beleg."}],"beispiel":{"titel":"Pyramide und Trichter lesen","text":"Das erste Schaubild ist die Pyramide mit fünf Stufen. Unten, am breitesten: 1 Anekdoten, 2 Expertenmeinungen. Dann 3 Beobachtungsstudien und 4 randomisierte kontrollierte Studien. Ganz oben: 5 systematische Reviews und Meta-Analysen. Je höher, desto aussagekräftiger. Das zweite Schaubild zeigt zwei Trichter. Jeder Punkt ist eine Studie, unten die kleinen, oben die großen. Links ist der Trichter symmetrisch: alles wurde veröffentlicht. Rechts fehlt die Ecke unten links, die kleinen Studien mit kleiner oder negativer Wirkung. Das ist die volle Schublade. Turner wies sie 2008 nicht mit einem Trichter nach, sondern über die Akten der FDA."},"merksatz":"Frag bei jedem Beleg, auf welcher Stufe er steht und was in der Schublade fehlen könnte.","pruefen":[{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"4c2a5410e2456350","vermerk":"Bestand"},"frage":"Auf welcher Stufe der Pyramide steht eine einzelne Geschichte wie die von Onkel Helmut?","optionen":["Auf Stufe 3, bei den Beobachtungsstudien, weil es ja ein echter Mensch erlebt hat.","Auf Stufe 5, bei den systematischen Reviews, weil sie zu 100 Prozent wahr ist.","Auf Stufe 1, bei den Anekdoten, auf der breiten Basis."],"richtig":2,"erklaerung":"Eine einzelne Geschichte ist eine Anekdote. Sie kann wahr sein und trotzdem wenig beweisen, weil sie nicht gegen Zufall und Verzerrung gefiltert ist."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"1fd9564174eabc52","vermerk":"Bestand"},"frage":"Im rechten Trichter fehlt die Ecke unten links. Was bedeutet das?","optionen":["Es gab nie Studien mit negativer Wirkung, die Behandlung hilft also ganz sicher.","Kleine Studien mit schwacher oder negativer Wirkung fehlen, die Wirkung wirkt zu groß.","Große Studien wurden nachträglich gefälscht, damit das Bild schöner aussieht."],"richtig":1,"erklaerung":"Wenn alles veröffentlicht würde, wäre der Trichter symmetrisch. Die leere Ecke zeigt die Schublade: Die Studien existieren vermutlich, aber man sieht sie nicht."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Was fand Turner 2008 laut Buch beim Vergleich von Fachliteratur und FDA-Akten?","optionen":["94 Prozent der veröffentlichten Studien waren positiv, bei der FDA angemeldet nur 51 Prozent.","51 Prozent der veröffentlichten Studien waren positiv, bei der FDA angemeldet 94 Prozent.","Beide Quellen zeigten ungefähr gleich viele Erfolge, der Unterschied war gering."],"richtig":0,"erklaerung":"Wer nur las, was gedruckt war, überschätzte die Wirkung. Die negativen Studien waren großenteils nie erschienen oder so umgeschrieben worden, dass sie wie Erfolge aussahen."}],"werkstuecke":["A.2 Die Hierarchie der Evidenz","A.24 Die Anatomie einer Studie, zweiter Blick","1.2.6 Die Hierarchie der Evidenz","VII.2 KI-Ergebnis ≠ Beleg (Kasten)"],"buch":"Landkarte der Realität, Band 1 (Kapitel Die Hierarchie der Evidenz), Glossar, Gebiet A: Die Werkzeuge des Denkens, und Anhang VII.2 (Kasten KI-Ergebnis ≠ Beleg)","schaubilder":["schaubild-2-evidenzpyramide","schaubild-10-trichterplot"],"hinweis":"Hinweis: Diese Lektion erklärt, wie man Zahlen und Behauptungen prüft. Sie ist keine Behandlungs- oder Gesundheitsempfehlung und ersetzt keine ärztliche Beratung."},{"id":"b","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"01e02d27951ee2f3","vermerk":"Bestand"},"gebiet":"B","titel":"Warum täuscht mich mein eigener Kopf?","kern":"Unser Denken hat bekannte, typische Fehler. Wenn du sie kennst, erwischst du sie schneller bei dir selbst.","dauer":6,"schritte":[{"titel":"Die „Bugs“ im System","text":"Das Gebiet B nennt typische Denkfehler „Bugs“, also Programmfehler in unserer Betriebssoftware. Das Buch betont: Sie sind oft die Kehrseite von genialen Abkürzungen, die uns früher das Überleben sicherten. Es geht nicht darum, sie auszurotten, denn sie gehören zum Menschsein. Es geht darum, sie bei sich selbst im Moment ihres Auftretens zu bemerken. Ein Fund ist also kein Makel, sondern ein Gewinn."},{"titel":"Wir sehen, was wir schon glauben","text":"Der Bestätigungsfehler. Im Beispiel des Buches hält ein Detektiv den Gärtner für schuldig. Danach sieht er nur noch, was dazu passt, und übergeht den Einbruch am Fenster. Das Buch nennt drei Ebenen. Wir suchen einseitig, wir deuten einseitig, und wir erinnern uns einseitig. Ein Gegenmittel ist die Frage: „Was wäre der stärkste Beweis gegen meine Position?“"},{"titel":"Was leicht einfällt, wirkt wichtig","text":"Die Verfügbarkeitsheuristik, also eine Faustregel im Kopf: Wir halten etwas für wahrscheinlich, wenn uns Beispiele leicht einfallen. Nach Bildern von einem Hai-Angriff wirkt das Meer bedrohlich. Die Autofahrt zum Supermarkt hat keine dramatischen Bilder. Das Buch belegt aber: Das Risiko, dabei tödlich zu verunglücken, ist statistisch um ein Vielfaches höher als das, von einem Hai getötet zu werden. Emotion, Lebhaftigkeit, Nähe in der Zeit und ständige Wiederholung machen Dinge „verfügbar“."},{"titel":"Schon bezahlt heißt nicht weitermachen","text":"Die Versunkene-Kosten-Falle: Du hast 25 Euro für Kino und Popcorn ausgegeben, und der Film ist furchtbar. Du bleibst trotzdem, weil das Geld sonst „verschwendet“ wäre. Das Geld ist aber so oder so weg. Entscheidend ist nur, was dir die nächsten 90 Minuten bringen. Die Frage des Buches: „Würde ich heute einsteigen, wenn mir das jemand zum ersten Mal anbieten würde?“"},{"titel":"Der blinde Fleck","text":"Die größte Falle ist der blinde Fleck. Wir erkennen Denkfehler bei anderen leicht, bei uns selbst kaum. Von innen sehen wir meist gute Absichten, bei anderen sehen wir nur das Verhalten. Laut Buch hilft auch Wissen über Denkfehler nicht von allein. Hilfreicher ist Feedback von außen: Bitte eine Person, der du vertraust und die anderer Meinung ist, dein Argument zu zerlegen, und hör nur zu."},{"titel":"Eine berühmte Kurve, die keine Messung ist","text":"Die bekannte Kurve vom „Gipfel der Ahnungslosigkeit“ über das „Tal der Verzweiflung“ bis zum Plateau ist laut Buch eine Illustration, keine Messung. Kruger und Dunning verglichen 1999 zu einem einzigen Zeitpunkt vier Leistungsviertel. Das schwächste lag beim 12. Perzentil und hielt sich für das 68., das beste lag beim 86. und hielt sich für das 74. Alle schätzten sich in einem engen Band ein. Wie viel davon echte Blindheit und wie viel Statistik ist, bleibt umstritten. Das Schaubild zeigt beides."}],"beispiel":{"titel":"Gedankenspiel: Saras Buch","text":"Gedankenspiel: Sara liest ein Buch und ist bei Seite 200 von 400. Es quält sie. Sie denkt: „Ich habe doch schon so viel gelesen.“ Das ist der typische Satz der Versunkene-Kosten-Falle. Die gelesene Zeit bekommt sie nicht zurück, egal was sie tut. Sie stellt sich die Frage: „Würde ich dieses Buch heute anfangen?“ Lautet die Antwort Nein, darf sie es zuklappen. Das ist kein Scheitern, sondern ein Fund: Sie hat ihren Denkfehler rechtzeitig bemerkt."},"merksatz":"Denkfehler gehören zu uns. Wer sie bei sich selbst bemerkt, hat gewonnen und nichts verloren.","pruefen":[{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"5594c9fab3c29f10","vermerk":"Bestand"},"frage":"Was beschreibt der Bestätigungsfehler?","optionen":["Wir ändern unsere Meinung sofort, wenn uns jemand widerspricht oder etwas Neues zeigt","Wir vergessen schnell, was wir gelesen haben, besonders bei langen Texten","Wir suchen, deuten und erinnern so, dass es zu unserem Glauben passt"],"richtig":2,"erklaerung":"Der Bestätigungsfehler wirkt auf drei Ebenen: bei der Suche, bei der Deutung und bei der Erinnerung. Deshalb können zwei Menschen mit denselben Informationen zu gegensätzlichen Schlüssen kommen."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Erklärung nennt das Buch als Autorität (Konzept 6.2); in Phase 3 umschreiben.","frage":"Warum wirkt ein Hai-Angriff gefährlicher als eine Autofahrt?","optionen":["Das dramatische Bild ist leicht verfügbar, die Statistik bleibt blass","Haie sind statistisch weit gefährlicher als Autofahrten","Autofahren ist laut Statistik völlig ungefährlich"],"richtig":0,"erklaerung":"Nicht die Häufigkeit, sondern die Leichtigkeit, mit der uns ein Bild einfällt, prägt das Gefühl. Die Autofahrt hat keine dramatischen Bilder, obwohl sie laut Buch statistisch um ein Vielfaches riskanter ist."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Was hilft laut Buch gegen den blinden Fleck?","optionen":["Viel über Denkfehler lesen, dann ist man gegen sie weitgehend immun","Eine vertraute Person mit anderer Meinung bitten, das eigene Argument zu zerlegen","Fest an die eigene Objektivität glauben und Kritik nicht an sich heranlassen"],"richtig":1,"erklaerung":"Von innen finden wir den blinden Fleck nicht, deshalb braucht es den Blick von außen. Wissen allein schützt nicht, es macht uns oft nur besser darin, Fehler bei anderen zu sehen."}],"werkstuecke":["B.1 Bestätigungsfehler (Confirmation Bias)","B.2 Der Dunning-Kruger-Effekt","B.3 Die Verfügbarkeitsheuristik","B.6 Die Versunkene-Kosten-Falle (Sunk Cost Fallacy)","B.29 Der blinde Fleck des Skeptikers (Bias Blind Spot)"],"buch":"Landkarte der Realität, Glossar, Gebiet B: Die „Bugs“ im System (kognitive Verzerrungen)","schaubild":"schaubild-9-dunning-kruger"},{"id":"c","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"f84564ebd3925f87","vermerk":"Bestand"},"gebiet":"C","titel":"Warum hat es bei mir doch geholfen?","kern":"Du lernst vier Naturprinzipien kennen, mit denen du Heilversprechen und Wundergeschichten fair und ruhig prüfen kannst.","dauer":7,"schritte":[{"titel":"Der Satz, den jeder kennt","text":"„Aber bei mir hat es doch geholfen!“ Diesen Satz hörst du oft, wenn es um Wundermittel geht. Das Buch nimmt ihn ernst. Die Erfahrung ist echt, und die Besserung auch. Offen bleibt nur eine Frage: Woher kam sie? Naturwissenschaft liefert dafür feste Prinzipien, die sich nicht durch Abstimmung oder gutes Zureden ändern lassen. Du musst keine Physikerin und kein Biologe sein. Vier Kernideen reichen schon."},{"titel":"Erwartung wirkt wirklich","text":"Der Placebo-Effekt ist eine nachweisbare Reaktion auf eine Scheinbehandlung, ausgelöst allein durch den Glauben an ihre Wirkung. Er ist nicht „nur Einbildung“. Eine Zuckerpille kann laut Buch die Ausschüttung körpereigener Endorphine auslösen, also natürlicher Schmerzmittel. Aufwendigere Scheinbehandlungen scheinen stärker zu wirken: Bei der Migräne-Vorbeugung sprachen 58 Prozent auf eine Schein-Operation an (nur zwei Studien), 38 auf Schein-Akupunktur und 22 auf Placebo-Tabletten (Meissner u. a., 2013). Das Gegenstück heißt Nocebo, also negative Erwartung, die echte Beschwerden erzeugen kann."},{"titel":"Die Zeit heilt mit","text":"Viele Krankheiten werden von allein besser, das nennt das Buch den natürlichen Verlauf. Dazu kommt die Regression zur Mitte: Nach einem extremen Messwert liegt der nächste wahrscheinlich näher am Durchschnitt. Menschen suchen Hilfe oft genau am schlimmsten Punkt. Danach wird es oft ohnehin besser, und die Besserung bekommt das zuletzt angewendete Mittel gutgeschrieben. Placebo, Verlauf und Regression zusammen erzeugen ein überzeugendes, aber trügerisches Gefühl von Wirkung."},{"titel":"Die Menge macht den Unterschied","text":"Ein weiteres Prinzip heißt Dosis-Wirkungs-Beziehung. Das Buch zitiert Paracelsus (Sieben Defensiones, 1538): „allein die Dosis macht, daß ein Ding kein Gift ist“. Es gibt demnach keine „giftigen“ Stoffe an sich, sondern giftige Mengen. Selbst Wasser ist in extremen Mengen tödlich. Eine Schlagzeile, die nur nennt, dass ein Stoff gefunden wurde, verschweigt das Wichtigste, nämlich wie viel. Die Frage nach der Menge entwaffnet viel Panikmache."},{"titel":"Woher kommt die Energie?","text":"Der Erste Hauptsatz der Thermodynamik sagt: Energie wird weder erzeugt noch vernichtet, nur umgewandelt. Das Buch nennt es „kein kostenloses Mittagessen“. Behauptungen über „freie Energie“ oder Energie, die ohne physikalische Wechselwirkung heilen soll, müssen deshalb erklären, wo die Energie herkommt und wo sie hingeht. Die Frage dazu lautet: Zeig mir den Energiefluss. Ist „Energie“ nur ein Bild, dann ist das in Ordnung, solange niemand es als Physik verkauft."}],"beispiel":{"titel":"Gedankenspiel: Der Glücksschal","text":"Stell dir Tobi vor, eine erfundene Figur. Er hat eine Pechsträhne: Mehrere Spiele in Folge gehen schief. Dann zieht er den alten Schal seines Opas an, und prompt läuft es wieder normal. „Der Schal wirkt!“, sagt er. Das Buch würde fragen: War die Pechsträhne ein extremer Ausschlag? Dann kehrt nach einem Ausreißer vieles ohnehin zum Durchschnitt zurück. Tobi muss den Schal deshalb nicht hergeben. Er weiß nur nicht, ob der Schal etwas bewirkt hat."},"merksatz":"Besserung nach einer Behandlung ist noch kein Beweis, dass die Behandlung gewirkt hat.","pruefen":[{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Erklärung nennt das Buch als Autorität (Konzept 6.2); in Phase 3 umschreiben.","frage":"Eine Erkältung wird am dritten Tag, auf dem Höhepunkt der Symptome, mit einem „Energie-Tee“ „behandelt“. Vier Tage später geht es besser. Was folgt daraus?","optionen":["Der Tee hat bewiesenermaßen gewirkt, denn die Reihenfolge stimmt.","Nichts Sicheres, denn Erkältungen werden meist von allein besser.","Der Tee hat nicht gewirkt, weil Erkältungen niemals besser werden."],"richtig":1,"erklaerung":"Das Buch nennt das natürlichen Verlauf und Regression zur Mitte. Weil die Besserung auch ohne Tee zu erwarten war, beweist die bloße Reihenfolge nichts."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Was sagt das Buch über den Placebo-Effekt?","optionen":["Er ist nur Einbildung und verändert im Körper gar nichts Messbares.","Er wirkt ausschließlich bei Menschen, die leicht zu täuschen sind.","Er ist eine messbare Reaktion auf die Erwartung, kein bloßes Einbilden."],"richtig":2,"erklaerung":"Laut Buch kann eine Scheinbehandlung zum Beispiel körpereigene Endorphine freisetzen. Der Effekt ist also real, wird aber oft mit der spezifischen Wirkung einer Behandlung verwechselt."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"758764367130bc62","vermerk":"Bestand"},"frage":"In einer Schlagzeile heißt es: „Giftstoff in Lebensmittel gefunden!“ Welche Frage stellt das Dosis-Prinzip als Erstes?","optionen":["Wie viel wurde gefunden, und wie verhält sich die Menge zum Grenzwert?","Klingt der Name des Stoffes gefährlich genug, um ihn zu meiden?","Ist der Stoff künstlich hergestellt worden?"],"richtig":0,"erklaerung":"Die Menge entscheidet, ob ein Stoff schadet. Eine Meldung ohne Mengenangabe und Grenzwert lässt genau die Information weg, die man zum Einordnen braucht."}],"werkstuecke":["C.4.5 Der Placebo- & Nocebo-Effekt","C.4.6 Natürlicher Krankheitsverlauf & Regression zur Mitte","C.4.7 Die Dosis-Wirkungs-Beziehung","C.1.2 Entropie & Die Gesetze der Thermodynamik"],"buch":"Landkarte der Realität, Glossar, Gebiet C: Die Architektur der Realität","hinweis":"Hinweis: Diese Lektion erklärt, wie man über Heilversprechen nachdenkt. Sie ist keine Behandlungsempfehlung und ersetzt keine ärztliche Beratung. Bei Beschwerden wende dich an eine Ärztin, einen Arzt oder eine Apotheke."},{"id":"c2","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"d1c003fce70d90a8","vermerk":"Bestand"},"gebiet":"C","titel":"Risiken fair vergleichen","kern":"Wer Risiken mit einem gemeinsamen Maßstab und einer Skala vergleicht statt nach Gefühl, sieht, was wirklich groß ist und was nur beängstigend wirkt.","dauer":6,"hinweis":"Hinweis: Diese Lektion erklärt, wie man Zahlen und Behauptungen prüft. Sie ist keine Behandlungs- oder Gesundheitsempfehlung und ersetzt keine ärztliche Beratung.","schaubilder":["schaubild-12-em-spektrum","schaubild-13-tote-je-twh"],"schritte":[{"titel":"Gefühlte und gezählte Gefahr","text":"Manche Gefahren fühlen sich riesig an, andere kaum. Das Buch nennt Gründe dafür: Eine Gefahr wirkt größer, wenn sie unsichtbar ist, nicht freiwillig eingegangen wird, katastrophal enden kann, der Wissenschaft unbekannt scheint oder spätere Generationen trifft. Das sagt etwas über den Schrecken, nicht über die Größe des Risikos. Wo sich zählen lässt, lohnt es sich, beides zu trennen."},{"titel":"Strahlung ist nicht gleich Strahlung","text":"Das Wort „Strahlung“ klingt nach einer einzigen Sache. Das Buch zeigt, dass sie das nicht ist. Radiowellen, Mikrowellen, Infrarot, sichtbares Licht, Ultraviolett, Röntgen und Gamma gehören zu einer Reihe, dem elektromagnetischen Spektrum. Im Schaubild im nächsten Schritt steigt die Energie der Lichtteilchen von links nach rechts. Wer „Strahlung“ sagt, muss also fragen: Welche, und wo auf dieser Reihe?"},{"titel":"Die Ionisierungsgrenze","text":"Strahlung kann Erbgut schädigen, wenn sie Elektronen aus Atomen schlagen kann. Dazu braucht ein Lichtteilchen eine Mindestenergie. Sie wird erst am kurzwelligen Ende des Ultravioletts erreicht, bei rund 10 Elektronenvolt. Diese Stelle heißt Ionisierungsgrenze. Davor liegt der nichtionisierende Bereich: Erwärmung ist möglich, aber es wird kein Elektron gelöst. Ultraviolett kann das Erbgut trotzdem schädigen. Dahinter liegt der ionisierende Bereich, der Elektronen lösen kann."},{"titel":"Eine Skala, die Zehnerschritte zeigt","text":"Das zweite Schaubild zeigt Todesfälle je Terawattstunde. Das ist die Zahl der Toten je erzeugter Energiemenge, Unfälle und Luftverschmutzung zusammengezählt. Die Zahlen reichen von sehr klein bis sehr groß. Darum nutzt das Bild eine logarithmische Skala: Jede Linie bedeutet zehnmal mehr als die davor. So passen 25 und 0,03 auf ein Blatt. Zwei Werte in derselben Größenordnung liegen im selben Zehnerbereich."},{"titel":"Fair zählen, sauber trennen","text":"Fair ist ein Vergleich, wenn für alle dasselbe gezählt wird. Das Buch zählt Tschernobyl und Fukushima mit. Es hält auch fest: Die Kohletoten sterben leise, an Feinstaub, ohne Bild. Die Atomtoten sterben in einem Ereignis mit Namen. Ob eine Gesellschaft etwas bauen sollte, ist eine andere Frage, die Kosten, Müll und Politik betrifft. Das Buch trennt beide Fragen. Zählen beantwortet nur die erste."}],"beispiel":{"titel":"So liest du die beiden Schaubilder","text":"Schaubild 12: Links stehen die Radiowellen, rechts die Gammastrahlen, nach rechts steigt die Energie. Die Ionisierungsgrenze liegt am kurzwelligen Ende des Ultravioletts. 5G (um 3,6 und um 40 GHz) sitzt weit links davon und trägt ein Millionstel bis ein Sechzigtausendstel der nötigen Energie. Schaubild 13: Nach dem Schaubild liegen die Werte etwa bei Kohle 25, Öl 18, Erdgas 3, Wasser 1,3, Kernenergie 0,03, Wind 0,04 und Sonne 0,02 Tote je Terawattstunde. Das Buch nennt Erdgas „knapp 3“ und Kernenergie „0,03 bis 0,05“. Kernenergie, Wind und Sonne liegen in derselben Größenordnung, weit unter Kohle, Öl und Erdgas."},"merksatz":"Vergleiche Risiken mit demselben Maßstab auf derselben Skala, nicht nach der Lebhaftigkeit der Bilder.","pruefen":[{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Das Buch sagt: Ein 5G-Lichtteilchen trägt ein Millionstel (um 3,6 GHz) bis ein Sechzigtausendstel (um 40 GHz) der Energie, die zum Ionisieren nötig wäre. Wo liegt 5G im Spektrum?","optionen":["Rechts der Ionisierungsgrenze, bei Röntgen und Gamma","Weit links der Grenze, im nichtionisierenden Bereich","Genau auf der Ionisierungsgrenze im Ultraviolett"],"richtig":1,"erklaerung":"Die Grenze liegt am kurzwelligen Ende des Ultravioletts, und ein Millionstel bis ein Sechzigtausendstel der nötigen Energie liegt weit darunter. Mobilfunk bleibt deshalb im nichtionisierenden Bereich."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Erklärung nennt das Buch als Autorität (Konzept 6.2); in Phase 3 umschreiben.","frage":"Im zweiten Schaubild stehen etwa Kernenergie 0,03, Wind 0,04 und Sonne 0,02. Wie liegen sie zueinander?","optionen":["Kernenergie ist mehr als hundertmal so hoch wie Wind und Sonne","Kernenergie liegt um mehrere Zehnerpotenzen unter Wind und Sonne","Alle drei liegen in derselben Größenordnung"],"richtig":2,"erklaerung":"0,03, 0,04 und 0,02 liegen nahe beieinander, also im selben Zehnerbereich. Das Buch sagt ausdrücklich, Kernenergie liege in derselben Größenordnung wie Wind und Sonne."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"312fdda7d83516bd","vermerk":"Bestand"},"frage":"Was bedeutet es, Risiken „mit Maßstab“ zu vergleichen?","optionen":["Für alle dasselbe zählen, hier Tote je Energiemenge","Das Ereignis wählen, das am eindrücklichsten im Gedächtnis ist","Die Gefahr nehmen, die sich am bedrohlichsten anfühlt"],"richtig":0,"erklaerung":"Nur wenn für jede Stromquelle dasselbe gezählt wird, lassen sich die Zahlen vergleichen. Bilder und Gefühl gewichten dagegen nach Lebhaftigkeit statt nach Häufigkeit."}],"werkstuecke":["Akte #26: Die Angst vor dem Atom (Warum die gefühlte Gefahr nicht die gezählte ist)","Akte #28: Der Sender auf dem Dach (Die Angst vor 5G)","C.1.1 Urknall & Die vier fundamentalen Kräfte","C.4.7 Die Dosis-Wirkungs-Beziehung"],"buch":"Landkarte der Realität, Anhang, Akten, Gebiet C: Die Architektur der Realität"},{"id":"d","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"adb79a356ea6c84b","vermerk":"Bestand"},"gebiet":"D","titel":"Wenn Argumente unfair werden","kern":"Du lernst vier gängige Tricks in Debatten zu erkennen und mit einer ruhigen Frage zurück zur Sache zu finden.","dauer":8,"schritte":[{"titel":"Sache und Person trennen","text":"Beim Ad hominem, lateinisch „gegen den Menschen“, wird nicht das Argument angegriffen, sondern die Person, die es vorbringt. Ob eine Aussage stimmt, hängt aber nie davon ab, wer sie sagt. Auch ein unordentlicher Mechaniker kann bei der Steuerkette recht haben. Prüfen, wer bezahlt, ist erlaubt und ein Grund, Daten besonders kritisch zu prüfen. Es widerlegt das Argument aber nicht. Das muss an der Sache selbst geschehen."},{"titel":"Der Strohmann","text":"Beim Strohmann-Argument baut jemand eine verzerrte Karikatur deiner Position und greift dann diese an. Das geht durch Übertreiben, Vereinfachen, Herausgreifen des schwächsten Punktes oder reines Erfinden. Der Sieg wirkt leicht, weil gar kein echter Kampf stattfand. Ein Warnzeichen ist der Impuls, zu sagen: „Das habe ich doch gar nicht gesagt!“ Das Gegenstück ist der Stahlmann, die faire und starke Fassung der Gegenseite."},{"titel":"Nur zwei Türen?","text":"Das falsche Dilemma schrumpft viele Möglichkeiten auf zwei, meist extreme. „Entweder du bist für uns oder gegen uns.“ Wer eine dritte Option sucht, gilt dann als feige oder unentschlossen. Echte Dilemmata gibt es, aber selten. Das Buch beschreibt ein Warnzeichen: Du fühlst dich gedrängt, zwischen zwei schlechten Optionen zu wählen. Dann lohnt sich der Blick auf die Optionen C, D und E, die niemand genannt hat."},{"titel":"Wer den Rahmen wählt","text":"Framing heißt, ein Thema durch Wortwahl, Bilder und Kontext in einen Deutungsrahmen zu setzen. Der Rahmen bestimmt, was wir sehen und was draußen bleibt. „10 Prozent Sterblichkeit“ und „90 Prozent Überlebensrate“ sagen dasselbe, wirken aber verschieden. Frames sind laut Buch unvermeidlich und nicht per se böse. Gefährlich wird es, wenn wir den Rahmen nicht bemerken oder er Fakten ausblendet, die nicht hineinpassen."},{"titel":"Die ruhige Gegenfrage","text":"Gegen jeden dieser Tricks hilft eine freundliche Frage. Beim Angriff auf die Person: „Betrachten wir nur das Argument selbst.“ Beim Strohmann: „Habe ich dich richtig verstanden, dass ich gesagt habe …?“ Beim falschen Dilemma: „Welche Optionen haben wir noch nicht bedacht?“ Beim Rahmen: „Welche anderen Rahmen gäbe es?“ Das ist kein Angriff. Seziert wird die Behauptung, nicht der Mensch."},{"titel":"Rückzug in die Burg","text":"Die Motte-and-Bailey-Täuschung ist nach einer mittelalterlichen Burg benannt. Im offenen Gehöft, dem Bailey, steht die kühne, kaum zu verteidigende Behauptung, etwa: Unsere Methode heilt jede Krankheit. Wird sie angegriffen, zieht sich jemand in den Turm auf dem Hügel zurück, die Motte: Eine positive Einstellung hilft dem Heilungsprozess. Ist der Angriff vorbei, geht es unauffällig zurück ins Gehöft. Das Schaubild zeigt beide Wege. Frag deshalb: Welche Aussage meinst du eigentlich?"},{"titel":"Ein Etikett ist noch kein Beweis","text":"Ein Name für ein schwaches Argument widerlegt noch nichts. Das Buch warnt vor dem Fehlschluss-Fehlschluss. Wer sagt „Schau dir diesen heißen Sommer an, der Klimawandel ist real!“, verwechselt Wetter und Klima. Wer daraus folgert, an der Erwärmung sei nichts dran, begeht seinerseits einen Fehlschluss, denn den Trend zeigen Messreihen über Jahrzehnte. Prüf deshalb zweierlei: ob das Etikett passt und was für die Behauptung selbst spricht."}],"beispiel":{"titel":"Gedankenspiel: Das Straßenfest","text":"Stell dir einen erfundenen Gemeinderat vor. Frau Weber schlägt vor, am Samstag das Straßenfest eine Stunde früher zu beenden. Herr Kurz antwortet: „Sie wollen also alle Feste verbieten und unser Viertel stilllegen!“ Das ist ein Strohmann. Frau Weber bleibt ruhig und sagt: „Das ist eine interessante Kritik, aber sie richtet sich nicht gegen das, was ich gesagt habe. Mein eigentlicher Punkt war: eine Stunde früher, weil die Nachbarn Ruhe brauchen.“ Damit ist die Debatte wieder bei der Sache."},"merksatz":"Frage immer zuerst: Geht es gerade um die Sache oder um etwas anderes?","pruefen":[{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"d7aa7c08254d991f","vermerk":"Bestand"},"frage":"Du sagst bei der Autowerkstatt: „Was wissen Sie schon? Sie rauchen ja!“ Was ist daran der Fund?","optionen":["Das ist ein Strohmann, weil die Diagnose übertrieben dargestellt wird.","Das ist ein falsches Dilemma, weil nur zwei Möglichkeiten genannt werden.","Das ist ein Ad hominem, weil die Person statt der Diagnose angegriffen wird."],"richtig":2,"erklaerung":"Ob die Steuerkette übergesprungen ist, hängt nicht davon ab, ob der Mechaniker raucht. Die Debatte wechselt von der Sachebene zur Person."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"13079fb983bf02d4","vermerk":"Bestand"},"frage":"Jemand sagt: „Wer nicht für unseren Plan ist, ist dagegen.“ Welche Gegenfrage passt am besten?","optionen":["Welche anderen Möglichkeiten gibt es noch?","Wer bezahlt euch eigentlich für diesen Plan hier?","Hast du mich eben wirklich richtig verstanden?"],"richtig":0,"erklaerung":"Der Satz verengt alles auf zwei Optionen. Die Gegenfrage öffnet den Raum wieder und sucht die Optionen, die verschwiegen wurden."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"8e4ca02c021b802e","vermerk":"Bestand"},"frage":"Zwei Ärzte nennen dieselbe Zahl: einer „10 Prozent Sterblichkeit“, der andere „90 Prozent Überlebensrate“. Was zeigt das?","optionen":["Einer der beiden Ärzte muss die Zahl falsch berechnet haben.","Dieselbe Tatsache kann je nach Rahmen unterschiedlich wirken.","Prozentzahlen sind grundsätzlich nicht aussagekräftig."],"richtig":1,"erklaerung":"Die Information ist identisch, nur der Deutungsrahmen unterscheidet sich, vom Verlust zum Gewinn. Das ist der Kern von Framing."}],"werkstuecke":["D.1.1 Ad Hominem (Der Angriff auf die Person)","D.1.2 Das Strohmann-Argument","D.1.3 Falsches Dilemma (Falsche Dichotomie)","D.2.3 Framing (Die Macht des Deutungsrahmens)","D.3.2 Die Motte-and-Bailey-Täuschung"],"buch":"Landkarte der Realität, Glossar, Gebiet D: Rhetorische Taktiken & verbale Kriegsführung (mit dem Kasten zum Gebrauch der Etiketten)","schaubild":"schaubild-15-motte-and-bailey"},{"id":"e","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"4c86aa4f9f424b66","vermerk":"Bestand"},"gebiet":"E","titel":"Warum schweigen alle, wenn alle schweigen?","kern":"Gruppen lenken uns stärker, als wir merken, und wer die Mechanismen kennt, kann sich im richtigen Moment trotzdem zu Wort melden.","dauer":6,"schritte":[{"titel":"Zwei Denker in deinem Kopf","text":"Das Buch ist aus Bausteinen gebaut, den Werkstücken. Eines davon beginnt mit einer Frage: Ein Schläger und ein Ball kosten zusammen 1,10 Euro. Der Schläger kostet 1 Euro mehr als der Ball. Die schnelle Antwort „10 Cent“ ist falsch, richtig sind 5 Cent. Das Buch erklärt es so: System 1 ist der Autopilot, schnell und automatisch. System 2 ist der Pilot, langsam und logisch. Der Pilot läuft meist im Sparmodus und muss bei Bedarf bewusst zugeschaltet werden."},{"titel":"Der Test mit den Linien","text":"Stell dir vor, du sitzt mit sieben anderen Personen im Raum. Ihr sollt sagen, welche von drei Linien so lang ist wie eine Vergleichslinie. Die richtige Antwort ist offensichtlich. Doch sechs Personen nennen nacheinander dieselbe falsche. Dann bist du dran. In den Experimenten von Solomon Asch gaben 75 Prozent der Teilnehmer in mindestens einer Runde nach. Das Buch nennt das Konformität: Wir passen uns der Gruppe an. Das ist menschlich und kein Makel."},{"titel":"Warum wir uns anpassen","text":"Das Buch nennt zwei Gründe. Erstens den informativen Einfluss: Wir denken, wenn alle das sagen, müssen sie etwas wissen, das wir nicht wissen. Zweitens den normativen Einfluss: Wir wollen gemocht und akzeptiert werden und fürchten Ausgrenzung. Er wirkt stärker, wenn man unter den Augen der Gruppe antworten muss, und war in Aschs Nachbefragungen der am häufigsten genannte Grund. Anpassung ist oft nützlich, zum Beispiel bei Verkehrsregeln. Gefährlich wird sie, wenn sie dein eigenes Urteil außer Kraft setzt."},{"titel":"Das Schweigen der Zeugen","text":"Latané und Darley füllten einen Raum mit Rauch. War die Versuchsperson allein, meldeten 75 Prozent den Rauch. Waren drei echte Versuchspersonen zusammen im Raum, meldete nur in 38 Prozent der Gruppen überhaupt jemand den Rauch. Bei zwei Schauspielern, die den Rauch ignorierten, waren es 10 Prozent. Ein Grund heißt Diffusion der Verantwortung: Jeder denkt, jemand anderes kümmert sich. Der Zuschauereffekt bremst den Einzelnen. Er macht Menschenmengen aber nicht zu Zuschauern, denn in gut neun von zehn gefilmten Konflikten griff mindestens ein Umstehender ein."},{"titel":"Der Kaiser ist nackt","text":"Im Märchen sieht niemand die neuen Kleider des Kaisers, aber jeder denkt, er sei der Einzige. Das Buch nennt das pluralistische Ignoranz: Eine Mehrheit lehnt privat etwas ab, glaubt aber, die anderen fänden es gut. Beispiel: Am Ende eines Vortrags fragt der Professor nach Fragen. Alle schweigen, weil jeder denkt, nur er habe nichts verstanden. Gegenmittel: Stelle eine offene Frage. In einem Notfall sprich eine einzelne Person direkt an."}],"beispiel":{"titel":"Gedankenspiel: Die stille Klasse","text":"Gedankenspiel: Eine Lehrerin erklärt ein schwieriges Thema und fragt dann: „Alles klar?“ Niemand meldet sich. Mia hat nichts verstanden, aber sie sieht ringsum ruhige Gesichter. Sie denkt: „Dann bin ich wohl die Einzige.“ Genauso denken auch Jonas und Leyla. Alle drei schweigen, jede aus demselben Grund. Dann sagt Mia: „Das ist wahrscheinlich eine dumme Frage, aber könnten Sie den zweiten Schritt noch einmal zeigen?“ Mehrere Köpfe nicken erleichtert. Mias Mut hat die Illusion beendet."},"merksatz":"Wenn alle schweigen, weißt du nicht, was die anderen denken. Frag trotzdem.","pruefen":[{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"b34f3e8a081817a1","vermerk":"Bestand"},"frage":"Warum gaben viele Teilnehmer im Linien-Experiment die falsche Antwort, obwohl sie die richtige sahen?","optionen":["Sie konnten die Linien wirklich nicht unterscheiden.","Sie wollten dazugehören und fürchteten, aufzufallen.","Sie wollten dem Versuchsleiter absichtlich schaden."],"richtig":1,"erklaerung":"Viele Teilnehmer wussten, was richtig war. Der Wunsch nach Zugehörigkeit und die Angst vor Ausgrenzung, der normative Einfluss, war für viele stärker als der Blick auf die Linien und in Aschs Nachbefragungen der am häufigsten genannte Grund."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Erklärung nennt das Buch als Autorität (Konzept 6.2); in Phase 3 umschreiben.","frage":"Im Rauch-Experiment meldeten allein 75 Prozent den Rauch, mit zwei passiven Schauspielern nur 10 Prozent. Was zeigt das?","optionen":["Menschen in Gruppen sind grundsätzlich herzlos.","Rauch ist in Gruppen schwerer zu riechen.","Die Anwesenheit anderer kann den Einzelnen bremsen."],"richtig":2,"erklaerung":"Das Buch erklärt die Bremse mit Diffusion der Verantwortung und Angst vor Blamage. Latané und Darley vermuteten, dass nicht Bösartigkeit, sondern die Dynamik der Gruppe dahintersteckt."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Alle im Hörsaal schweigen, weil jeder denkt, nur er habe nichts verstanden. Wie heißt das im Buch?","optionen":["Pluralistische Ignoranz","System-2-Denken","Diffusion durch Autorität"],"richtig":0,"erklaerung":"Bei der pluralistischen Ignoranz passt sich eine Mehrheit an eine nur eingebildete Mehrheitsmeinung an. Jeder deutet das Schweigen der anderen falsch als deren wahre Überzeugung."}],"werkstuecke":["E.1.1 System 1 & System 2 (Der Autopilot und der Pilot)","E.2.1 Konformität","E.2.3 Das Schweigen der Zeugen (Diffusion der Verantwortung & Der Zuschauereffekt)","E.2.5 Das Märchen von des Kaisers neuen Kleidern (Pluralistische Ignoranz)"],"buch":"Landkarte der Realität, Glossar, Gebiet E: Die Architektur der Gesellschaft","schaubild":"schaubild-3-system-1-und-2"},{"id":"f","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"abe1108591de08e3","vermerk":"Bestand"},"gebiet":"F","titel":"Wissenschaft, Wagnis oder bemalte Pappe?","kern":"Du lernst, eine Idee nach ihrer Methode einzuordnen statt nach ihrer Seltsamkeit, und erkennst so Pseudowissenschaft und Verschwörungsmythen an ihrer Struktur.","dauer":6,"schritte":[{"titel":"Drei Architekten","text":"Das Buch besteht aus Bausteinen, den Werkstücken. Eines erzählt von drei Architekten. Der Wissenschaftler legt berechnete, nachprüfbare Pläne vor. Der Grenzwissenschaftler zeigt eine kühne Skizze mit einem neuen Material und sagt offen, dass es spektakulär scheitern könnte. Der Pseudowissenschaftler kommt mit leeren Händen und sagt, das Gebäude stehe durch Glauben, und stürze es ein, sei der Glaube zu schwach gewesen."},{"titel":"Die Methode zählt, nicht die Seltsamkeit","text":"Das Buch warnt vor zwei Fallen. Der Dogmatiker lehnt jede seltsame Idee ab und verpasst vielleicht Neues. Der Naive hält jede „unterdrückte“ Idee für Grenzwissenschaft und fällt auf Scharlatane herein. Der Ausweg ist die Frage nach der Methode. Wichtig ist auch der Unterschied zwischen „nicht bewiesen“, das ist der Zustand der Grenzwissenschaft, und „widerlegt“. Grenzwissenschaft sagt: Hier ist meine Idee, so können wir sie testen."},{"titel":"Die Landebahn ohne Flugzeuge","text":"Im Zweiten Weltkrieg landeten amerikanische Flugzeuge auf Pazifikinseln und brachten Reichtümer. Nach dem Krieg bauten Inselbewohner Landebahnen nach und setzten einen Mann in eine Holzhütte, mit zwei Holzstücken als Kopfhörern und Bambusstäben als Antennen, damit die Flugzeuge zurückkehren. Die Form stimmte, aber die Flugzeuge kamen nicht. Es fehlte das Verständnis der zugrundeliegenden Prinzipien. Der Nobelpreisträger Richard Feynman nannte das Cargo-Kult. Der Unterschied zur echten Wissenschaft ist radikale Ehrlichkeit, auch gegenüber Beweisen, die der eigenen Idee widersprechen."},{"titel":"Die Checkliste für Wissenschafts-Imitation","text":"Das Buch bietet eine Checkliste mit zehn Punkten. Einige davon: Die Beweislast wird umgekehrt, der Skeptiker soll das Gegenteil beweisen. Die Behauptung ist unfalsifizierbar, also nicht widerlegbar. Als Beweis dienen Anekdoten. Die etablierte Wissenschaft wird als Feind dargestellt. Mit dem Glauben ist ein Geschäft verbunden. Es müssen nicht alle zehn Punkte zutreffen. Treffen aber viele zu, spricht das mit hoher Wahrscheinlichkeit für einen Cargo-Kult."},{"titel":"Sieben Warnsignale für den Kaninchenbau","text":"Auch für Verschwörungsmythen gibt es einen Kompass mit sieben Warnsignalen. Dazu gehören ein allmächtiger, böser Feind, die umgekehrte Beweislast und fehlende Beweise, die als Beweis gelten. Auch eine unfalsifizierbare Erzählung und die Trennung in „Erwachte“ und „Schlafschafe“ zählen dazu. Je mehr Signale zutreffen, desto wahrscheinlicher ist es ein Kaninchenbau. Das Buch rät, auf die Struktur einer Geschichte zu achten, nicht nur auf die „Fakten“."}],"beispiel":{"titel":"Gedankenspiel: Der Fokus-Kristall","text":"Gedankenspiel: Ein erfundener Händler verkauft den „Fokus-Kristall“, der angeblich die Konzentration steigert. Auf seiner Seite steht ein eigenes „Institut“ mit vielen Fachwörtern. Du fragst nach einer Studie. Er antwortet: „Beweis mir doch, dass er nicht wirkt.“ Als Belege nennt er Erfolgsgeschichten von Kunden. Wirkt der Kristall bei dir nicht, sei dein Glaube zu schwach. Zufällig verkauft er auch teure Seminare. Du setzt mindestens fünf Haken auf der Checkliste, ohne ein Wort über den Kristall selbst gestritten zu haben."},"merksatz":"Frag nicht, wie seltsam eine Idee klingt, sondern ob sie testbar ist und scheitern darf.","pruefen":[{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Woran erkennst du laut Buch den Unterschied zwischen Grenzwissenschaft und Pseudowissenschaft?","optionen":["Grenzwissenschaft klingt weniger seltsam.","Pseudowissenschaft verwendet keinerlei Fachwörter.","An der Methode: Grenzwissenschaft ist testbar."],"richtig":2,"erklaerung":"Entscheidend ist die Methode, nicht die Seltsamkeit. Grenzwissenschaft ist spekulativ, aber prinzipiell überprüfbar. Pseudowissenschaft ahmt Wissenschaft nur nach und weicht dem Scheitern aus."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Erklärung nennt das Buch als Autorität (Konzept 6.2); in Phase 3 umschreiben.","frage":"Was fehlte den Inselbewohnern im Cargo-Kult, obwohl sie die äußere Form perfekt kopierten?","optionen":["Das Verständnis der Prinzipien dahinter.","Genug Bambus, um die Landebahnen zu bauen.","Ein Funkgerät aus echtem Metall."],"richtig":0,"erklaerung":"Sie ahmten nur die Form nach. Das unsichtbare Fundament, das Verständnis der Prinzipien, fehlte. Das Buch nutzt dieses Bild, Feynmans Cargo-Kult, als Metapher für Pseudowissenschaft."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Erklärung nennt das Buch als Autorität (Konzept 6.2); in Phase 3 umschreiben.","frage":"Jemand sagt: „Beweis mir, dass es nicht stimmt!“ Welches Warnsignal ist das?","optionen":["Eine elitäre Gruppe von „Wissenden“.","Die Beweislast wird umgekehrt.","Ein allmächtiger, böser Feind."],"richtig":1,"erklaerung":"In der Wissenschaft muss der Behauptende die Beweise liefern. Wer die Last auf den Skeptiker abwälzt, kehrt diese Regel um, und das Buch führt das bei beiden Checklisten als Warnsignal auf."}],"werkstuecke":["F.0 Die Landkarte des Wissens (Wissenschaft vs. Grenzwissenschaft vs. Pseudowissenschaft)","F.1.1 Pseudowissenschaft","F.1.3.1 Der Kaninchenbau (Checkliste Verschwörungsmythen)","F.1.5 Cargo-Kult-Wissenschaft (Die Landebahn ohne Flugzeuge)"],"buch":"Landkarte der Realität, Glossar, Gebiet F: Die Landkarte der Irrationalität"},{"id":"f2","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"34109b83375855c2","vermerk":"Bestand"},"gebiet":"F","titel":"Wenn eine Gruppe alles kontrolliert","kern":"Mit vier Fragen an Verhalten, Information, Gedanken und Gefühle erkennst du, ob eine Gruppe ihre Mitglieder steuert, und du prüfst dabei die Struktur, nicht den Glauben.","dauer":6,"schritte":[{"titel":"Starke Gruppen sind etwas Gutes","text":"Gemeinschaften können Halt, Sinn und Freundschaft geben. Das Buch sagt ausdrücklich: Starke, engagierte Gemeinschaften sind eine positive Kraft. Die Frage ist nicht, ob eine Gruppe wichtig für ihre Mitglieder ist. Die Frage ist, ob sie beginnt, die persönliche Autonomie (Selbstbestimmung) und das kritische Denken ihrer Mitglieder zu untergraben. Das Buch nennt diesen Moment den Kipppunkt. Erst dann wird aus Nähe Kontrolle."},{"titel":"Die Struktur prüfen, nicht den Glauben","text":"Der Berater Steven Hassan, selbst ein Aussteiger, hat das „BITE-Modell“ entwickelt, eine als Beratungshilfe nützliche Checkliste. Sie hilft, manipulative Systeme zu erkennen. Wichtig ist der Blickwinkel: Es geht nicht um den Glauben einer Gruppe (Theologie), sondern um Struktur und Verhalten. Du fragst also nicht, ob etwas wahr oder schön klingt. Du fragst, wie die Gruppe mit ihren Mitgliedern umgeht. Das Schaubild im nächsten Schritt zeigt dir die vier Bereiche."},{"titel":"Verhalten und Information","text":"B steht für Behavior Control, Verhaltenskontrolle. Hier wird reguliert, wo, wie und mit wem jemand lebt, was er isst, anzieht und wie er schläft. Geld wird zur Abhängigkeit. I steht für Information Control. Der Zugang zu kritischen Quellen wird eingeschränkt, Wissen wird hierarchisch verteilt, etwa als „Geheimwissen“, und Mitglieder sollen einander melden. Das Schaubild zeigt beide Bereiche oben."},{"titel":"Gedanken und Gefühle","text":"T steht für Thought Control, Gedankenkontrolle. Die Ideologie gilt als einzige, absolute Wahrheit. Geladene Sprache rahmt die Wirklichkeit neu, und kritisches Denken wird als egoistisch abgestempelt. Gedankenstoppende Klischees würgen Zweifel ab. E steht für Emotional Control. Liebe („Love Bombing“) und Angst wechseln sich ab, Schuld und Scham dienen als Mittel. Im Schaubild stehen diese zwei Bereiche unten."},{"titel":"Mehr Punkte, mehr Kontrolle","text":"Das Buch hält fest: Nicht jede Gruppe, die einige Merkmale aufweist, ist ein Kult. Aber je mehr Punkte der Checkliste mit hoher Intensität erfüllt sind, desto höher ist der Grad der Kontrolle. Das Buch sagt, das Modell lasse sich auch auf eine Zweierbeziehung anwenden, in der ein Partner den anderen durch Isolation und psychologische Manipulation kontrolliert."},{"titel":"Was der Bundestag dazu sagte","text":"Die Enquete-Kommission „Sogenannte Sekten und Psychogruppen“ des Bundestages hielt 1998 manipulatives Einwirken von Gruppen auf Einzelne für vielfach belegt. Die Kontrolle, die Hassan beschreibt, sei aber nicht in jedem Fall manipulativ, ein Stück davon gehöre zu jeder Gemeinschaft. Den Begriff „Sekte“ lehnte die Kommission wegen seiner abwertenden Färbung ab. Menschen, die sich solchen Gruppen zuwenden, seien keine „passiven Opfer“, sondern brächten eigene Bedürfnisse mit."}],"beispiel":{"titel":"Das Schaubild lesen, mit einem Gedankenspiel","text":"Das Schaubild hat vier Felder, jedes mit einem Buchstaben im farbigen Kreis. Oben links steht B (Verhalten), oben rechts I (Information). Unten links steht T (Gedanken), unten rechts E (Emotionen). Je Feld stehen vier bis fünf Merkmale. Ganz unten liest du: „Es geht nicht um den Glauben (Theologie), sondern um Struktur und Verhalten“. Gedankenspiel: Ein erfundener Verein verbietet seinen Mitgliedern jede Zeitung von außen und nennt Kritiker „Verräter“. Das trifft Information (I) und Gedanken (T). Zwei Merkmale allein machen ihn noch nicht zum Kult. Aber du weißt, wo du weiterfragen kannst."},"merksatz":"Prüfe die Struktur, nicht den Glauben: Verhalten, Information, Gedanken und Gefühle, und je mehr Punkte zutreffen, desto größer die Kontrolle.","pruefen":[{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Erklärung nennt das Buch als Autorität (Konzept 6.2); in Phase 3 umschreiben.","frage":"Worauf richtet das BITE-Modell den Blick?","optionen":["Auf Struktur und Verhalten der Gruppe","Auf die Frage, ob der Glaube der Gruppe wahr ist","Auf die Persönlichkeit einzelner Mitglieder"],"richtig":0,"erklaerung":"Das Buch sagt: Es geht nicht um den Glauben (Theologie), sondern um Struktur und Verhalten. So wird die Gruppe geprüft und nicht der Mensch, der in ihr lebt."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"5f3003fa04445fbd","vermerk":"Bestand"},"frage":"Im Schaubild steht der Buchstabe I für einen der vier Bereiche. Welcher ist es?","optionen":["Individualität und freie Selbstbestimmung","Information Control (Informationskontrolle)","Ideologie als einzige, absolute Wahrheit"],"richtig":1,"erklaerung":"I steht für Information Control. Dazu gehören eingeschränkter Zugang zu externen Quellen, „Geheimwissen“ für höhere Stufen und das gegenseitige Melden. Ideologie gehört zu T, Gedankenkontrolle."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Eine Gruppe erfüllt einzelne Merkmale der Checkliste. Was folgt laut Buch daraus?","optionen":["Sie ist damit eindeutig ein Kult, mehr braucht es nicht.","Sie ist ein Kult, sobald ein einziger Bereich zutrifft.","Nicht zwingend, aber mehr Punkte bedeuten mehr Kontrolle."],"richtig":2,"erklaerung":"Das Buch hält fest: Nicht jede Gruppe mit einigen Merkmalen ist ein Kult. Die Checkliste zeigt einen Grad: Je mehr Punkte mit hoher Intensität zutreffen, desto höher ist die manipulative Kontrolle."}],"schaubilder":["schaubild-14-bite-modell"],"werkstuecke":["F.1.4 Manipulative Systeme (Kulte)"],"buch":"Landkarte der Realität, Glossar, Gebiet F: Die Landkarte der Irrationalität"},{"id":"g","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"899e73b9b038f609","vermerk":"Bestand"},"gebiet":"G","titel":"Wörter, die mehr tun, als sie sagen","kern":"Manche Wörter sind Kampfbegriffe mit Geheimbedeutung, und wenn du sie erkennst, lässt du dich nicht mehr von ihnen lenken.","dauer":6,"schritte":[{"titel":"Sprache als Werkzeug","text":"Geschlossene Glaubenssysteme erschaffen ihre eigene Sprache. Das Buch sagt: Dieses Vokabular ist keine zufällige Ansammlung von Jargon. Es ist ein Werkzeug. Es soll die eigene Gruppe einen, denn wer den Code spricht, gehört dazu. Es markiert die Außengruppe, vereinfacht komplexe Realitäten und lenkt das Denken in feste Bahnen. Jedes Wort dieser Art hat zwei Bedeutungen: eine wörtliche und eine kodierte. Genau die zweite sollst du hören lernen."},{"titel":"Aufwachen und Schlafschaf","text":"Wörtlich ist „Aufwachen“ der Übergang vom Schlaf in den Wachzustand. Kodiert meint es einen fast religiösen Erweckungsmoment: Jemand glaubt, die „Wahrheit“ hinter einer vermeintlichen Verschwörung erkannt zu haben. „Schlafschaf“ nennt dann alle, die noch das normale Bild der Welt teilen. Das Wort verbindet Schlaf und Schaf. Das Buch nennt das eine Form der Entmenschlichung. Es macht es nahezu unmöglich, Außenstehende noch als ernsthafte Gesprächspartner zu sehen, und ihre Kritik kann ignoriert werden."},{"titel":"Eine Tugend wird gekapert","text":"„Selbst nachdenken“ und „eigene Recherche“ klingen wunderbar. Wörtlich sind sie ein Kernprinzip der Aufklärung: Quellen prüfen und sich eine eigene Meinung bilden. Kodiert heißt es oft, etablierte Quellen pauschal abzulehnen und die „Wahrheit“ nur in der eigenen Echokammer zu suchen. Das Buch beobachtet eine Ironie: Die „eigene Recherche“ führt in diesen Kreisen bei allen zum selben vorgegebenen Ergebnis. Das ist Konformität, getarnt als Rebellion. Echtes Selbstdenken heißt, die eigenen Methoden und blinden Flecken zu prüfen."},{"titel":"Pauschale Etiketten","text":"„Mainstream-Medien“ oder „Lügenpresse“ kritisieren keinen einzelnen Fehler. Sie sind eine Generalanklage gegen die Presse als Ganzes. Laut Buch versiegeln sie die Echokammer, denn jede Nachricht von außen gilt dann als verdächtig. Sie tun so, als gäbe es nur eine Stimme, obwohl es viel Vielfalt gibt, von der taz bis zur NZZ. „Lügenpresse“ ist zudem historisch belastet: Der Begriff ist älter als der Nationalsozialismus und war spätestens im Ersten Weltkrieg ein nationalistischer Kampfbegriff. Die NS-Propaganda griff ihn später auf."},{"titel":"So antwortest du: nach dem Konkreten fragen","text":"Das Buch rät, nicht den Inhalt zu bekämpfen, sondern auf Genauigkeit zu bestehen. Bei „Lügenpresse“ fragst du: Welcher Artikel, wann, welche überprüfbare Falschaussage? Wurde sie korrigiert? Dasselbe Muster zeigt sich bei „Toxinen“ und „Schlacken“ aus der Detox-Werbung: Wie heißt das Toxin genau? Wie wurde es gemessen? Journalistische Fehler leugnest du dabei nicht. Du fragst freundlich nach Belegen, und du sprichst über die Behauptung, nicht über den Menschen."}],"beispiel":{"titel":"Gedankenspiel: Der Gruppenchat","text":"Gedankenspiel: Mara schreibt im Klassenchat: „Ich recherchiere selbst. Die Lügenpresse erzählt eh nur, was die Eliten wollen.“ Ihr Mitschüler Ben könnte antworten: „Du hast recht, selbst nachzudenken ist wichtig. Welchen Artikel meinst du? Was genau stimmte daran nicht, und wurde es später korrigiert?“ Ben streitet nicht über das Etikett und greift Mara nicht an. Er nimmt ihren Satz ernst und bittet um etwas Konkretes. So bleibt das Gespräch offen, und der Beleg entscheidet, nicht das Schlagwort."},"merksatz":"Frag bei geladenen Wörtern nach dem Konkreten: Wer genau, was genau, woran überprüfbar?","pruefen":[{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Was bewirkt das Wort „Schlafschaf“ laut Buch?","optionen":["Es ist ein harmloser Spitzname, der niemanden abwertet.","Es wertet Außenstehende ab, sodass sie kaum noch als ernsthafte Gesprächspartner gelten.","Es beschreibt sachlich Menschen, die an einer Schlafstörung leiden."],"richtig":1,"erklaerung":"Das Buch nennt das Wort eine Form der Entmenschlichung. Wer so benannt wird, dessen Kritik lässt sich leicht ignorieren, weil er die Wahrheit angeblich per Definition nicht sehen kann."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Was fällt dem Buch an der „eigenen Recherche“ in geschlossenen Kreisen auf?","optionen":["Sie führt in diesen Kreisen immer zu unabhängigem und neuem Wissen.","Sie wird in diesen Kreisen nur von ausgebildeten Fachleuten betrieben.","Sie führt bei allen zum selben Ergebnis: Konformität im Gewand der Rebellion."],"richtig":2,"erklaerung":"Wenn alle bei ihrer „eigenen“ Recherche zum gleichen Schluss kommen, deutet das auf Konformitätsdruck hin. Echtes Selbstdenken prüft auch die eigenen Methoden."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Welche Antwort passt am besten zum Vorgehen des Buches, wenn jemand „Lügenpresse“ sagt?","optionen":["Nach einem konkreten Fall fragen: Welcher Artikel, welche überprüfbare Falschaussage, wurde sie korrigiert?","Behaupten, dass Journalisten niemals Fehler machen und jede Kritik daher unberechtigt ist.","Zurückgeben: „Dann glaubst du eben jeden Unsinn, den man dir erzählt.“"],"richtig":0,"erklaerung":"Das Buch rät, auf Spezifität zu bestehen und Fehler nicht zu leugnen. Ein Gegen-Etikett wäre wieder nur ein pauschales Etikett statt eines Belegs."}],"werkstuecke":["G.1.1 „Aufwachen“ / „Schlafschaf“","G.1.2 „Selbst nachdenken“ / „Eigene Recherche“","G.2.2 „Mainstream-Medien“ / „Lügenpresse“","G.3.1 „Toxine“ / „Schlacken“ / „Entgiften“ (Detox)"],"buch":"Landkarte der Realität, Glossar, Gebiet G: Das Taktische Lexikon"},{"id":"h","status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"4edf1fcd12f6eaf0","vermerk":"Bestand"},"gebiet":"H","titel":"Streiten, ohne die Tür zuzuschlagen","kern":"Du lernst, hitzige Gespräche zu beruhigen und mit Neugier statt mit Angriff zu führen, damit sie nicht im Streit enden.","dauer":6,"schritte":[{"titel":"Das Ziel wechseln","text":"Das Buch beschreibt ein eskalierendes Gespräch als gekapertes Gespräch. Das impulsive System 1 hat die Kontrolle übernommen, das überlegende System 2 arbeitet nur noch als sein Anwalt. Dann ist niemand mehr an Fakten interessiert, es geht nur noch um Gewinnen und Gesichtsverlust. Ein Fakten-Argument kommt in diesem Moment kaum an und nährt eher den Streit. Darum der Wechsel: Dein erstes Ziel ist nicht mehr, Recht zu haben, sondern das Gespräch zu retten."},{"titel":"Gute Gründe unterstellen","text":"Das Prinzip der intellektuellen Barmherzigkeit bedeutet, die Motive des anderen im bestmöglichen Licht zu sehen: als Sorge, guten Willen oder ehrliche Suche nach Wahrheit, nicht als Dummheit oder Bosheit. Es ist ein Gegenmittel zum Fehler, andere sofort zu dämonisieren. Du greifst die Idee an, nicht die Person. Das heißt nicht, naiv zu sein. Wenn jemand systematisch Hass schürt, ist es naiv, von guten Absichten auszugehen. Dann beurteilst du seine Handlungen."},{"titel":"Zuhören, um zu verstehen","text":"Aktives Zuhören heißt, sich auf den Sprecher zu konzentrieren, statt nur auf die eigene Sprechpause zu warten. Das Buch nennt vier Techniken. Du gibst das Gehörte in eigenen Worten wieder (Paraphrasieren). Du benennst Gefühle. Du stellst offene Fragen, die nicht mit Ja oder Nein zu beantworten sind. Und du legst Ablenkungen weg, zum Beispiel das Handy. Die Papageien-Regel dazu: Fasse erst zusammen, was der andere sagt, bis er „Ja, genau“ antwortet."},{"titel":"Vier Griffe der Deeskalation","text":"Die Deeskalations-Matrix hat vier Techniken. Erstens: Gefühle bestätigen, nicht den Inhalt. Zweitens: „Ich“-Botschaften statt „Du“-Botschaften, etwa „Ich habe Schwierigkeiten, diese Logik nachzuvollziehen“ statt „Du bist irrational“. Drittens: Gemeinsamkeiten finden, zum Beispiel gleiche Ziele. Viertens: eine strategische Auszeit mit klarer Absicht, das Gespräch später fortzusetzen. Das Buch betont: Ein Gefühl zu bestätigen heißt nicht, dem Inhalt zuzustimmen."},{"titel":"Nach dem Weg fragen, nicht nach dem Ziel","text":"Street Epistemology fragt nicht, was jemand glaubt, sondern woher er es weiß. Du klärst die Behauptung, fragst nach der Sicherheit auf einer Skala von 0 bis 100 und dann: „Was ist deine Methode?“ Danach prüft ihr gemeinsam, ob diese Methode verlässlich ist. Ziel ist ein kleiner Stein des Zweifels, kein Geständnis. Bei reinen Fakten brauchst du das nicht. Und die Neugier muss ehrlich sein, sonst wirkt es wie ein Kreuzverhör."}],"beispiel":{"titel":"Gedankenspiel: Der Horoskop-Streit","text":"Gedankenspiel: Jonas sagt beim Abendessen: „Horoskope stimmen immer, das ist bewiesen!“ Seine Schwester Lea will schon loslegen, hält inne und fragt: „Du scheinst dir sehr sicher zu sein. Wie sicher, von 0 bis 100?“ „Neunzig.“ „Und was macht dich so sicher? Was ist deine Methode?“ Jonas erzählt von einem Monat, in dem alles passte. Lea sagt nicht „Du irrst“. Sie fragt: „Wie könnten wir prüfen, ob es am Horoskop lag?“ Beide bleiben im Gespräch."},"merksatz":"Hör zuerst zu, bleib freundlich und frag nach dem Weg zur Überzeugung, nicht nach ihrem Ergebnis.","pruefen":[{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Was ist laut Buch dein primäres Ziel, wenn ein Gespräch hitzig wird?","optionen":["Das Gespräch zu retten.","Den anderen mit möglichst vielen Fakten zu überzeugen.","Lauter zu werden, damit man dich hört."],"richtig":0,"erklaerung":"In einem hitzigen Moment ist das impulsive System 1 am Steuer, und Fakten-Argumente kommen kaum an und nähren eher den Streit. Wird System 1 beruhigt, bekommt das überlegende System 2 wieder eine Chance."},{"status":"entwurf","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"hinweis_intern":"Die Frage nennt das Buch (oder Prolog, Epilog, Autoren) als Autorität; muss als Anwendungs- oder Szenario-Aufgabe neu geschrieben werden (Konzept 6.2).","frage":"Du sagst: „Ich höre, wie wütend dich das macht.“ Was heißt das laut Buch?","optionen":["Du stimmst der Behauptung deines Gegenübers damit zu.","Du gibst damit deine eigene Position auf und lenkst ein.","Du erkennst das Gefühl an, ohne dem Inhalt zuzustimmen."],"richtig":2,"erklaerung":"Das Buch trennt das Bestätigen von Gefühlen und das Bestätigen von Inhalten. So bleibt der Kanal offen, ohne dass du falschen Aussagen zustimmst."},{"status":"freigegeben","bestand":{"stichtag":"2026-10-11","vermerk":"Bestand"},"freigabe":{"datum":"2026-10-11","pruefsumme":"961eb29281fa45cb","vermerk":"Bestand"},"frage":"Was untersucht Street Epistemology?","optionen":["Welche Studien die Behauptung des anderen widerlegen.","Die Methode, mit der jemand zu seiner Überzeugung gekommen ist.","Wie schnell sich jemand von Fakten überzeugen lässt."],"richtig":1,"erklaerung":"Die Methode greift nicht die Schlussfolgerung an, sondern das Verfahren dahinter. Die Person soll selbst prüfen, wie verlässlich ihr Weg zum Wissen ist."}],"werkstuecke":["H.1.3 Das Prinzip der intellektuellen Barmherzigkeit (Principle of Charity)","H.2.1 Die Deeskalations-Matrix","H.2.2 Street Epistemology (Die Sokratische Methode 2.0)","H.2.3 Die Kunst des aktiven Zuhörens"],"buch":"Landkarte der Realität, Glossar, Gebiet H: Die Schmiede (Mentale Resilienz & Taktische Kommunikation)"}]`);export{e as t};